// Jewel Engine: a flight through an endless crystal machine made of light.
// Space is repeated in every direction, mirrored into a kaleidoscope around
// the flight axis, then folded over and over (mirror, shift, turn), which
// turns one plain box into interlocking frames, blades and gears. Nothing
// is solid: each ray passes through everything and gathers glow from every
// wall it crosses, so you see the whole machine at once, layer behind
// layer. The fold angles follow the journey, so each beat re-gears the
// machine, and rings of light pulse through it. After kasari39's
// "Phantom Star".

#define TAU 6.28318531
#define PI 3.14159265

mat2 R1;
mat2 R2;
float SEG;
float OFF;

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

float map(vec3 p) {
  // One machine every 10 x 10 x 16 units.
  p.xy = mod(p.xy - 5.0, 10.0) - 5.0;
  p.z = mod(p.z, 16.0) - 8.0;
  // Kaleidoscope around the axis.
  float a = atan(p.y, p.x);
  a = abs(mod(a, 2.0 * SEG) - SEG);
  p.xy = length(p.xy) * vec2(cos(a), sin(a));
  for (int i = 0; i < 5; i++) {
    p = abs(p) - OFF;
    p.xy = R1 * p.xy;
    p.xz = R2 * p.xz;
  }
  vec3 b = abs(p) - vec3(0.4, 0.8, 0.3);
  return length(max(b, 0.0)) + min(max(b.x, max(b.y, b.z)), 0.0);
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;

  SEG = PI / float(facets);
  OFF = mix(1.1, 1.6, spread);
  R1 = rot(j * 0.037 + twist * 1.5);
  R2 = rot(j * 0.013 + 1.0);
  float hue = colour + j * 0.011;

  // The machine repeats every 16 units along the flight, so wrap it.
  float fly = mod(j * 0.5, 16.0);
  vec3 ro = vec3(0.0, 0.0, fly);
  p = rot(j * 0.021) * p;
  vec3 rd = normalize(vec3(p, mix(1.4, 0.45, fisheye)));
  // The view sways slowly off the axis.
  rd.xz = rot(0.35 * sin(j * 0.017)) * rd.xz;
  rd.yz = rot(0.25 * sin(j * 0.023 + 1.0)) * rd.yz;

  float t = 0.0;
  vec3 col = vec3(0.0);
  for (int i = 0; i < 44; i++) {
    vec3 pos = ro + rd * t;
    float d = max(abs(map(pos)), 0.02);
    float a = exp(-d * 5.5);
    // Rings of light travel outward through the structure.
    float ring = abs(mod(t - j * 2.0, 12.0) - 6.0);
    a *= 1.0 + 3.0 * pulse * smoothstep(4.5, 6.0, ring);
    col += palette(hue + t * 0.035 + length(pos.xy) * 0.05) * a;
    t += d * 0.8;
  }

  col *= 0.057 * mix(0.5, 2.0, glow);
  // Deepen the colours; only stacked walls reach white.
  col = mix(col, col * col, 0.6);
  col = 1.0 - exp(-col * 1.3);
  return clamp(col, 0.0, 1.0);
}
